import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SmoothArrowProps = Record<string, any>;

const SmoothArrow: React.FC<SmoothArrowProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 4,
  arrowColor = "#ffffff",
  arrowSize = 250,
  arrowStrokeWidth = 8,
  glowIntensity = 0.4,
  arrowStyle = "Standard",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Frame logic guarantees strict monotonicity because durationInSeconds >= 1 and fps >= 1
  const durationFrames = durationInSeconds * fps;
  const entryEnd = durationFrames * 0.3;
  const exitStart = durationFrames * 0.7;

  // 1. Primary Drop Animation (Y-Axis)
  const yDrop = interpolate(
    frame,
    [0, entryEnd, exitStart, durationFrames],
    [-height * 0.6, 0, 0, height * 0.6],
    {
      easing: Easing.bezier(0.42, 0, 0.58, 1), // Smooth ease-in-out
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 2. Continuous Hovering/Bobbing Effect while in center
  const hoverAmplitude = height * 0.015;
  const hoverY = Math.sin((frame - entryEnd) * 0.1) * hoverAmplitude;
  
  // Mix the hover effect smoothly so it only applies heavily when stationary
  const hoverMix = interpolate(
    frame,
    [
      entryEnd * 0.8, 
      entryEnd, 
      exitStart, 
      exitStart + (durationFrames - exitStart) * 0.2
    ],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const finalY = yDrop + hoverY * hoverMix;

  // 3. Motion Speed / Blur Simulation (Scale Y)
  const velocityScaleY = interpolate(
    frame,
    [
      0, 
      entryEnd * 0.5, 
      entryEnd, 
      exitStart, 
      exitStart + (durationFrames - exitStart) * 0.5, 
      durationFrames
    ],
    [1.4, 1.2, 1, 1, 1.2, 1.4],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 4. Entry and Exit Opacity Fades
  const opacity = interpolate(
    frame,
    [
      0, 
      entryEnd * 0.4, 
      exitStart + (durationFrames - exitStart) * 0.6, 
      durationFrames
    ],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const filterStyle = glowIntensity > 0 
    ? `drop-shadow(0px 0px ${glowIntensity * 40}px ${arrowColor})` 
    : "none";

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        fontFamily: "Inter",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transition: "none"
      }}
    >
      <div
        style={{
          width: arrowSize,
          height: arrowSize,
          opacity: opacity,
          transform: `translateY(${finalY}px) scaleY(${velocityScaleY})`,
          transformOrigin: "center center",
          filter: filterStyle,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 100 100"
          style={{ width: "100%", height: "100%", overflow: "visible", transition: "none" }}
          fill="none"
          stroke={arrowColor}
          strokeWidth={arrowStrokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          {arrowStyle === "Standard" && (
            <line x1="50" y1="10" x2="50" y2="90" />
          )}
          {arrowStyle === "Standard" ? (
            <polyline points="20,60 50,90 80,60" />
          ) : (
            <polyline points="20,35 50,65 80,35" />
          )}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default SmoothArrow;